import{_ as e,o as d,c as i,ao as l}from"./chunks/framework.CQwyKQFD.js";const y=JSON.parse('{"title":"The Knob Registry","description":"","frontmatter":{},"headers":[],"relativePath":"knobs.md","filePath":"knobs.md","lastUpdated":null}'),r={name:"knobs.md"};function a(g,t,n,s,h,o){return d(),i("div",null,[...t[0]||(t[0]=[l('<h1 id="The-Knob-Registry" tabindex="-1">The Knob Registry <a class="header-anchor" href="#The-Knob-Registry" aria-label="Permalink to &quot;The Knob Registry {#The-Knob-Registry}&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">Generated file — do not edit</p><p>Produced by <code>test/knob_registry.jl</code> from <code>src/</code>. To change a row, change the code or its <code># PDM:</code> marker and regenerate. <code>test/knob_registry_tests.jl</code> fails if this file is out of date.</p></div><p>Every <code>@load_preference</code> key in <code>src/</code> — 120 of them.</p><table tabindex="0"><thead><tr><th style="text-align:right;">Tier</th><th style="text-align:right;">Meaning</th></tr></thead><tbody><tr><td style="text-align:right;"><strong>Derived</strong></td><td style="text-align:right;">Default is a formula over detected hardware consts.</td></tr><tr><td style="text-align:right;"><strong>Measured</strong></td><td style="text-align:right;">Not derivable — the optimum depends on something we cannot detect. Wants a <code>tune!()</code> pin.</td></tr><tr><td style="text-align:right;"><strong>Literal</strong></td><td style="text-align:right;">A fixed value: a proven invariant, or a derivation that was tried and falsified.</td></tr><tr><td style="text-align:right;"><strong>Exempt</strong></td><td style="text-align:right;">Not hardware tuning at all — a sentinel or a capability flag.</td></tr></tbody></table><p><strong>Tier:</strong> 62 Derived · 10 Measured · 40 Literal · 8 Exempt. <strong>Default form</strong> (mechanical): 54 formula · 20 delegates · 6 sibling · 35 literal · 4 flag · 1 other.</p><h2 id="BLAS-1-SIMD-kernels" tabindex="-1">BLAS-1 SIMD kernels <a class="header-anchor" href="#BLAS-1-SIMD-kernels" aria-label="Permalink to &quot;BLAS-1 SIMD kernels {#BLAS-1-SIMD-kernels}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>axpy_dram</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">narrow 256-bit arm iff the datapath double-pumps; +17% Zen4, loses on Zen3.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>axpy_unroll</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_axpy_band(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>zaxpy_narrow</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">the criterion IS the datapath: narrow arm iff _datapath_bytes &lt;= 32.</td><td style="text-align:right;">n/a</td></tr></tbody></table><h2 id="BLAS-2-gemv/ger/trmv/trsv" tabindex="-1">BLAS-2 (gemv/ger/trmv/trsv) <a class="header-anchor" href="#BLAS-2-gemv/ger/trmv/trsv" aria-label="Permalink to &quot;BLAS-2 (gemv/ger/trmv/trsv) {#BLAS-2-gemv/ger/trmv/trsv}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>cgemv_mr</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">split accumulators need MR small enough to amortise A; 4 fits both register files.</td><td style="text-align:right;">low value</td></tr><tr><td style="text-align:right;"><code>cgemv_rb</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">L2/16: the m*n threshold where a resident panel stops beating a stream.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>cgemvn_nc</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">4 columns per panel, matching what OpenBLAS uses; not swept independently.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cgemvn_nc_big</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>3 * _vwidth(Float64) ÷ 2</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemvn_pf</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemvt_cfg</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Derived</td><td style="text-align:right;">_CGEMVT_CFG_BIG is already a complete _NVREG derivation.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>cgemvt_half</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemvt_nc</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">legacy pin, superseded by _cgemvt_cfg; retained only so an old preference still parses.</td><td style="text-align:right;">n/a, dead</td></tr><tr><td style="text-align:right;"><code>cgemvt_pf</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemvn_mb</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>max(_vwidth(Float64), _L1_BYTES ÷ 2 ÷ sizeof(Float64</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemvn_minner</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">panel-width regime inverts across µarchs (Zen3/Zen4 keep the gain, Zen5 reverts).</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>gemvn_minner_maxa</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>4 * _L3_BYTES</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemvn_np_narrow</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>max(2, _L1D_ASSOC - 2</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemvn_rb</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 64 : 448</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemvt_deep</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">NC=8 x U=4 gated on A &lt;= L2 and the register budget; both detected consts.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>gemvt_nc</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Literal</td><td style="text-align:right;">_ILP_TARGET predicts 8, every box measures 4; the derivation is falsified.</td><td style="text-align:right;">no, µarch-invariant</td></tr><tr><td style="text-align:right;"><code>gemvt_percol_amin</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Measured</td><td style="text-align:right;">window&#39;s lower edge; no formula places it (see gemvt_perscan).</td><td style="text-align:right;">candidate, cache-boundary set</td></tr><tr><td style="text-align:right;"><code>gemvt_percol_xmax</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Measured</td><td style="text-align:right;">window&#39;s upper edge, and the one worth money (Zen5 wants 4 KiB, not L1/2).</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>gemvt_perscan</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">every pair of boxes disagrees at some size; L1, L2, L3 and width all falsified.</td><td style="text-align:right;">not yet</td></tr><tr><td style="text-align:right;"><code>gemvt_pf</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">prefetch distance depends on L2 hit latency and the hw streamer, neither detected; bounds derived, choice measured.</td><td style="text-align:right;">candidate, 0/2/4/8 lines</td></tr><tr><td style="text-align:right;"><code>gemvt_u</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">row unroll capped by the register file: NC*U + U + 2 &lt;= _NVREG.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>ger_panel_np</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">optimum 8/4/1 on boxes that agree on L2/L3/width; tracks DRAM write streams.</td><td style="text-align:right;">22 s</td></tr><tr><td style="text-align:right;"><code>tri_c_blk_min</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 256 : 1024</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>tri_c_t_unb</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">complex transpose unblocked/blocked crossover.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>tri_nb</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>clamp(_round_dn(isqrt(_L1_BYTES ÷ 8), 16), 16, 64</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>tri_t_unb</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">unblocked/blocked crossover for the transpose path; blocking fixes a measured regression above it.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>trmv_f_dram</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Derived</td><td style="text-align:right;">majority criterion: switch once tri &gt; 2*L3. The 2 IS the 1/2.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>trmv_f_switch</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Derived</td><td style="text-align:right;">NOT Measure-tier debt, despite the label this line carried until 2026-08-21. It is a MAJORITY CRITERION over a derived quantity: switch to the narrow panel once more than half the triangle&#39;s stream is DRAM-served, i.e. <code>1 - L3/tri &gt; 1/2</code> &lt;=&gt; <code>tri &gt; 2*L3</code>. The 2 IS the 1/2 — it is not a tuned multiplier, and the cache term carries the hardware. Validated at the boundary: Zen3 n=4096 sits exactly AT 2*L3 and measured 0.973 either way, so the switch costs nothing where it fires.</td><td style="text-align:right;">n/a — Derived</td></tr><tr><td style="text-align:right;"><code>trmv_fused_min</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">a crossover set by call overhead vs vectorised work; sweepable without editing code.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>trsv_reg_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_SCALAR_FPREGS - 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>zhemv_pf</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>zhemv_pf_tiles</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">prefetch depth in tiles for the Hermitian mat-vec.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="BLAS-2-banded" tabindex="-1">BLAS-2 banded <a class="header-anchor" href="#BLAS-2-banded" aria-label="Permalink to &quot;BLAS-2 banded {#BLAS-2-banded}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>gbmv_conv_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 20 : 48</code></td><td style="text-align:right;">—</td></tr></tbody></table><h2 id="BLAS-2-packed" tabindex="-1">BLAS-2 packed <a class="header-anchor" href="#BLAS-2-packed" aria-label="Permalink to &quot;BLAS-2 packed {#BLAS-2-packed}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>spmv_panel</code></td><td style="text-align:right;">flag</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">boolean switch (path on/off), not a tuned size.</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>spmv_panel_minap</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_L1_BYTES</code></td><td style="text-align:right;">—</td></tr></tbody></table><h2 id="BLAS-3-trmm/trsm/syrk/symm" tabindex="-1">BLAS-3 (trmm/trsm/syrk/symm) <a class="header-anchor" href="#BLAS-3-trmm/trsm/syrk/symm" aria-label="Permalink to &quot;BLAS-3 (trmm/trsm/syrk/symm) {#BLAS-3-trmm/trsm/syrk/symm}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>chemm_pack_cut</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 4096 : 32</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>csymm_pack_cut</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Derived</td><td style="text-align:right;">same packed kernel as chemm, differing only by conjugation.</td><td style="text-align:right;">n/a, follows chemm</td></tr><tr><td style="text-align:right;"><code>csyr2k_fused_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 192 : 0</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>csyr2k_pack_cut</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">never swept: the retired ternary had two identical arms. Validated by gate only.</td><td style="text-align:right;">unswept</td></tr><tr><td style="text-align:right;"><code>csyrk_3m_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">lower bound for the 3M path; below it the Karatsuba overhead dominates.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>csyrk_pack_cut</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">trans=&#39;N&#39;: recurse below this rather than pack.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>csyrk_pack_cut_t</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">trans=&#39;C&#39;/&#39;T&#39;: packing wins almost always, hence the much lower cut.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>csyrk_unified_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 512 : 0</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>csyrk_unpack_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 16 : 192</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>ctrmm_pack</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>ctrmm_pack_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">complex trmm pack threshold.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>ctrsm_direct_max</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">trtri overhead plus extra flops sink small/mid n, so the direct path stops here.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>ctrsm_ncut</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">B-width cut: at or below it, the j-outer narrow recursion wins.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>ctrsm_rec_l</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">recursion cut for complex trsm side-L; per-box.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>gemmtrsm_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>min(8, (_GT_NREG - _GT_NRV - 2) ÷ _GT_NRV</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemmtrsm_nrv</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_GT_NREG &gt;= 32 ? 3 : 2</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>symm_pack_cut</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_symm_mat_max(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>syr2k_2pass</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Literal</td><td style="text-align:right;">two-pass enabled on AVX2 only (typemax disables it on AVX-512); measured, not derived.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>syr2k_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 2 : _MR</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>syr2k_nr</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Literal</td><td style="text-align:right;">drives its own microkernel, borrows gemm&#39;s _NR as a prior; unvalidated here.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>syr2k_pack_cut</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_rank_k_pack_cut(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>syrk_dbase</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">diagonal-block base; larger pushes work into efficient off-diagonal gemms.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>syrk_mr</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">rank-k row-block factor; 2 measured, not derived from the register file.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>syrk_pack_cut</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_rank_k_pack_cut(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>syrk_unified_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_vwidth(Float64) == 4 ? 48 : 0</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>trmm_ddirect</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">wide-SIMD-safe default for the direct path; per-box override without a code push.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>trmm_pack_min</code></td><td style="text-align:right;">other</td><td style="text-align:right;">Derived</td><td style="text-align:right;">5/2 x _GEMM_UNPACK_MAX, i.e. it follows gemm&#39;s own unpack bound.</td><td style="text-align:right;">n/a, follows gemm</td></tr><tr><td style="text-align:right;"><code>trmm_rkc</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Literal</td><td style="text-align:right;">own k-block, borrows gemm&#39;s _KC; a triangular operand packs differently.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>trmm_rpack</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">measured pack threshold; a box that disagrees pins it rather than editing.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>trsm_narrow_max</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">B-width below which the narrow path wins; measured, not derived.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>ztrsm_gt_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_ZGT_W</code></td><td style="text-align:right;">—</td></tr></tbody></table><h2 id="CPU-detection" tabindex="-1">CPU detection <a class="header-anchor" href="#CPU-detection" aria-label="Permalink to &quot;CPU detection {#CPU-detection}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>force_hooks</code></td><td style="text-align:right;">flag</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">boolean switch (path on/off), not a tuned size.</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>simd_bytes</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">the detected SIMD width itself; the override exists for cross-compile and trim builds, not tuning.</td><td style="text-align:right;">n/a</td></tr></tbody></table><h2 id="LAPACK-·-banded_chol" tabindex="-1">LAPACK · banded_chol <a class="header-anchor" href="#LAPACK-·-banded_chol" aria-label="Permalink to &quot;LAPACK · banded_chol {#LAPACK-·-banded_chol}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>pbtrf_cross_kd</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Literal</td><td style="text-align:right;">a crossover, not a width; lanes- and byte-budget derivations both falsified.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>pbtrf_nb</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">a panel width is counted in vector registers.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>pbtrf_nb_small</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">same unit; the F32 method is the pure formula _lanes(hw, Float32).</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>pbtrf_u_native_kd</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Literal</td><td style="text-align:right;">crossover; F64 breaks the l2/4096 rule its F32 sibling obeys.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="LAPACK-·-bunchkaufman" tabindex="-1">LAPACK · bunchkaufman <a class="header-anchor" href="#LAPACK-·-bunchkaufman" aria-label="Permalink to &quot;LAPACK · bunchkaufman {#LAPACK-·-bunchkaufman}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>sytrf_cmult</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">the complex multiplier is the Measure-tier knob here; gate-measured 3, the duel never picked it.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>sytrf_nb</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Derived</td><td style="text-align:right;">panel width from the shape function; only the multiplier below it is measured.</td><td style="text-align:right;">n/a</td></tr></tbody></table><h2 id="LAPACK-·-gbtrf" tabindex="-1">LAPACK · gbtrf <a class="header-anchor" href="#LAPACK-·-gbtrf" aria-label="Permalink to &quot;LAPACK · gbtrf {#LAPACK-·-gbtrf}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>gbtrf_cross</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Literal</td><td style="text-align:right;">crossover, derivation falsified; the C32 row is a 3-3 tie on Zen4.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>gbtrf_nb</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">banded LU panel width; the comment says outright it needs measuring, not assuming.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="LAPACK-·-lapack" tabindex="-1">LAPACK · lapack <a class="header-anchor" href="#LAPACK-·-lapack" aria-label="Permalink to &quot;LAPACK · lapack {#LAPACK-·-lapack}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>chol_base_split</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_INTEL_AVX2</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>chol_nb</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">trsm panel width, measured µarch-invariant; confirm on the fleet before deriving.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>chol_nc</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">syrk column block, same status as chol_nb.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cpotf2_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_cpotf2_mr(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cpotrf_base</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">32 + 4*lanes: a width-independent overhead floor plus a per-lane slope.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>cpotrf_nbmax</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_cpotrf_nbmax(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>potrf_base</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">recursion-overhead floor, µarch-flat at 16-32; the residency guess 64 is worse.</td><td style="text-align:right;">no</td></tr><tr><td style="text-align:right;"><code>potrf_base_f32</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Derived</td><td style="text-align:right;">sizeof ratio: F32 is half F64&#39;s bytes, so half the n.</td><td style="text-align:right;">n/a, follows potrf_base</td></tr><tr><td style="text-align:right;"><code>potrf_pad</code></td><td style="text-align:right;">flag</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">boolean switch (path on/off), not a tuned size.</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>potrf_upper_direct_max</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Measured</td><td style="text-align:right;">a tiny-n crossover inside a noisy band; only host measurement resolves it.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="LAPACK-·-packed_chol" tabindex="-1">LAPACK · packed_chol <a class="header-anchor" href="#LAPACK-·-packed_chol" aria-label="Permalink to &quot;LAPACK · packed_chol {#LAPACK-·-packed_chol}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>pptrf_blk_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">smallest n where unpacking pays; measured 2.26x at n=32, untested between 8 and 32.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>pptrf_blk_nb</code></td><td style="text-align:right;">sibling</td><td style="text-align:right;">Literal</td><td style="text-align:right;">own panel width, borrows _LU_NB, which is itself a falsified derivation.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>pptrf_spr_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">0 is the unset sentinel, not a size.</td><td style="text-align:right;">n/a</td></tr></tbody></table><h2 id="LAPACK-·-pstrf" tabindex="-1">LAPACK · pstrf <a class="header-anchor" href="#LAPACK-·-pstrf" aria-label="Permalink to &quot;LAPACK · pstrf {#LAPACK-·-pstrf}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>pstrf_fuse_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>(_L1_BYTES ÷ 2) ÷ _CACHELINE</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>pstrf_rowcache_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">measured on Zen4 F64 ONLY; not yet fleet-validated, so not a derivation.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="LAPACK-·-qr" tabindex="-1">LAPACK · qr <a class="header-anchor" href="#LAPACK-·-qr" aria-label="Permalink to &quot;LAPACK · qr {#LAPACK-·-qr}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>qr_nb_c</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">complex QR panel; the Zen4 sweet spot, keyed per box via Preferences.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="LAPACK-·-svd" tabindex="-1">LAPACK · svd <a class="header-anchor" href="#LAPACK-·-svd" aria-label="Permalink to &quot;LAPACK · svd {#LAPACK-·-svd}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>brd_nb</code></td><td style="text-align:right;">delegates</td><td style="text-align:right;">Literal</td><td style="text-align:right;">machine-INVARIANT 8 on three boxes and two ISAs; a formula taking hw and ignoring it was removed.</td><td style="text-align:right;">no</td></tr><tr><td style="text-align:right;"><code>bt_nb</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">back-transform block, measured invariant; confirm on a very-wide-register box before deriving.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="gemm-BLAS-3" tabindex="-1">gemm (BLAS-3) <a class="header-anchor" href="#gemm-BLAS-3" aria-label="Permalink to &quot;gemm (BLAS-3) {#gemm-BLAS-3}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>cgemm_3m</code></td><td style="text-align:right;">flag</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">boolean switch (path on/off), not a tuned size.</td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_3m_kmin</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">3M needs min(m,n,k) &gt;= this or the Karatsuba overhead dominates a thin gemm.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cgemm_3m_max</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">upper edge of the 3M window; above it the extra passes cost more than the flop cut.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cgemm_3m_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">lower edge of the 3M window on max(m,n,k).</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cgemm_kc</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_l1_block(_HW, ComplexF64, max(_CNR, _CNR_SMALL</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 1 : 2</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_nr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 6 : 4</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_nr_small</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 4 : _CNR</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_nrsmall_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 64 : 0</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cgemm_tiny</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">tiny-n bypass for complex gemm.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>cgemm_unpack_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 40 : 192</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>cuker_nr6_min</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_W64 == 4 ? 48 : typemax(Int</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_kc</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_kc(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_mr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_mr(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_mr1_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_mr1_max(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_nc</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_nc(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_nr</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_nr(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_split_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_split_max(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>gemm_unpack_max</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>_at_gemm_unpack_max(_HW)</code></td><td style="text-align:right;">—</td></tr><tr><td style="text-align:right;"><code>strassen</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Exempt</td><td style="text-align:right;">capability flag; Strassen&#39;s flop cut is ISA-independent.</td><td style="text-align:right;">n/a</td></tr><tr><td style="text-align:right;"><code>strassen_maxdepth</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">recursion depth cap; deeper trades flops for pack/add traffic.</td><td style="text-align:right;">candidate</td></tr><tr><td style="text-align:right;"><code>strassen_min</code></td><td style="text-align:right;">literal</td><td style="text-align:right;">Literal</td><td style="text-align:right;">split while min(m,n,k) &gt;= this; measured, and the base stays &gt;= ~min/2.</td><td style="text-align:right;">candidate</td></tr></tbody></table><h2 id="workspace" tabindex="-1">workspace <a class="header-anchor" href="#workspace" aria-label="Permalink to &quot;workspace {#workspace}&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:right;">Knob</th><th style="text-align:right;">Default</th><th style="text-align:right;">Tier</th><th style="text-align:right;">Why</th><th style="text-align:right;"><code>tune!()</code></th></tr></thead><tbody><tr><td style="text-align:right;"><code>l3_nb</code></td><td style="text-align:right;">formula</td><td style="text-align:right;">Derived</td><td style="text-align:right;">formula over detected consts: <code>clamp(_round_dn(isqrt(_L2_BYTES ÷ 32), 16), 16, 128</code></td><td style="text-align:right;">—</td></tr></tbody></table><hr><p>Const names, defaults and files are deliberately NOT tabulated: they are one <code>grep</code> away and made this table too wide to read. The knob key is the identifier that matters.</p>',39)])])}const x=e(r,[["render",a]]);export{y as __pageData,x as default};
